 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),2800);return()=>clearTimeout(t)},[toast]);
 useEffect(()=>{if(!onlineLeague||!supabaseReady||!user)return;let alive=true;const load=async()=>{const [m,r,s]=await Promise.all([supabase.from('league_members').select('id,user_id,display_name,club,tier,manager_state,joined_at').eq('league_id',onlineLeague.id).order('joined_at'),supabase.from('online_results').select('*').eq('league_id',onlineLeague.id).order('created_at',{ascending:false}).limit(25),supabase.from('online_league_standings').select('*').eq('league_id',onlineLeague.id).order('points',{ascending:false})]);if(alive){setOnlineMembers(m.data||[]);setOnlineResults(r.data||[]);setOnlineStandings(s.data||[]);}};load();const channel=supabase.channel('league-'+onlineLeague.id).on('postgres_changes',{event:'*',schema:'public',table:'league_members',filter:`league_id=eq.${onlineLeague.id}`},load).on('postgres_changes',{event:'INSERT',schema:'public',table:'online_results',filter:`league_id=eq.${onlineLeague.id}`},load).subscribe();return()=>{alive=false;supabase.removeChannel(channel)}},[onlineLeague,user]);
 const fixture=gm?nextFixture(gm):null;const report=lastMatch||(gm?.lastResult||null);const daysToNext=fixture?fixture.day-gm.lastDay:0;
