 const play=()=>{if(gm.status==='은퇴'){notify('은퇴한 감독은 경기를 진행할 수 없습니다.');return;}if(gm.pendingPlayoff){notify('승격 플레이오프를 먼저 진행하세요.');return;}const started=beginLiveMatch(gm,{rotation:fixture?.type==='리그'?rotation:cupXI,press,line,tempo,formation,width,selectedXI:startingXI,selectedRoles,selectedPositions:Object.fromEntries(startingXI.map((id,i)=>[id,['골키퍼','수비','수비','수비','수비','중원','중원','중원','공격','공격','공격'][i]])),selectedPositionDetails:Object.fromEntries(startingXI.map((id,i)=>[id,['골키퍼','왼쪽 풀백','왼쪽 센터백','오른쪽 센터백','오른쪽 풀백','수비형 미드필더','왼쪽 중앙 미드필더','오른쪽 중앙 미드필더','왼쪽 윙어','스트라이커','오른쪽 윙어'][i]]))});if(started.error){notify(started.error);return;}setLiveMatch(started.match);setLastMatch(null);setPostMatchStage('');setGm({...gm,postMatchStage:''});notify('킥오프! 경기 진행 중입니다.');};
 const advance=async choice=>{if(!liveMatch)return;const r=advanceLiveMatch(gm,liveMatch,choice);if(r.error){notify(r.error);return;}if(r.result){const fallbackInterview={questionIndex:0,question:'오늘 경기 결과를 어떻게 평가하십니까?',options:['선수들의 투지를 칭찬한다','전술적 판단의 책임을 인정한다','다음 경기 반등을 약속한다'],questions:[{question:'오늘 경기 결과를 어떻게 평가하십니까?',options:['선수들의 투지를 칭찬한다','전술적 판단의 책임을 인정한다','다음 경기 반등을 약속한다']},{question:'다음 경기에서 어떤 점을 보완하겠습니까?',options:['공격 전개를 개선하겠다','수비 조직을 다듬겠다','선수단을 믿고 준비하겠다']}],reporter:{name:'경기 담당 기자',outlet:'TOUCHLINE SPORTS',photo:'/players/reporter-1.png'}};const finalReport={...r.result,stats:r.result.stats||r.gm.lastResult?.stats||r.gm.matchStats||null,interview:r.result.interview||r.gm.interview||r.gm.lastResult?.interview||fallbackInterview};setGm({...r.gm,interview:finalReport.interview,postMatchStage:'stats'});setLastMatch(finalReport);setLiveMatch(null);setPostMatchStage('stats');setTab('경기');notify(`${r.result.gf}-${r.result.ga} 경기 종료${r.gm.lastWagePayment?.day===r.gm.lastDay&&r.gm.lastWagePayment?.amount?` · 주급 ${money(r.gm.lastWagePayment.amount)} 지급`:''} · 경기 통계를 확인하세요`);if(user&&onlineLeague&&supabaseReady){const f=r.result.fixture;await supabase.from('online_results').insert({league_id:onlineLeague.id,user_id:user.id,club:gm.club,opponent:f.opponent,competition:f.type,score:`${r.result.gf}-${r.result.ga}`,result:r.result.win?'승리':r.result.draw?'무승부':'패배'});await supabase.from('league_members').update({club:r.gm.club,tier:r.gm.tier,manager_state:r.gm}).eq('league_id',onlineLeague.id).eq('user_id',user.id);}}else setLiveMatch(r.match);};
 const makeSub=()=>{if(!liveMatch)return;const r=makeManualSubstitution(liveMatch,subOut,subIn,gm.squad||[]);if(r.error){notify(r.error);return;}setLiveMatch(r.match);setSubOut('');setSubIn('');notify('선수 교체를 완료했습니다.');};
 const negotiatePlayer=p=>{const raw=window.prompt('이적 제안 금액을 억 원 단위로 입력하세요.',String(Math.round((p.fee||0)/100000000)));if(raw===null)return;const r=makeTransferNegotiation(gm,p.id,Number(raw)*100000000);if(r.error){notify(r.error);return;}setGm(r.gm);notify(r.message||'이적 협상 결과를 확인하세요.');};
