 const signIn=async()=>{if(!supabaseReady){setAuthMsg('온라인 서버 설정이 필요합니다. .env 파일에 Supabase URL과 공개 키를 입력하세요.');return;}setBusy(true);const{error}=await supabase.auth.signInWithOtp({email});setBusy(false);setAuthMsg(error?.message||'로그인 링크를 이메일로 보냈습니다. 메일함을 확인하세요.');};
 const createOnline=async()=>{if(!user){notify('온라인 리그는 먼저 로그인해야 합니다.');return;}setBusy(true);const{data,error}=await supabase.rpc('create_league',{p_name:leagueName,p_visibility:leaguePrivacy});setBusy(false);if(error){notify(error.message);return;}setOnlineLeague(data);notify('온라인 리그를 만들었습니다. 초대 코드를 공유하세요.');};
 const joinOnline=async()=>{if(!user){notify('온라인 리그는 먼저 로그인해야 합니다.');return;}setBusy(true);const{data,error}=await supabase.rpc('join_league',{p_code:joinCode.trim().toUpperCase()});setBusy(false);if(error){notify(error.message);return;}setOnlineLeague(data);notify('리그에 참가했습니다.');};
